import pandas as pd

def compute_feature(card, disp):
    merged = pd.merge(card, disp, left_on='disp_id', right_on='disp_id')
    filtered = merged[(merged['type'] == 'OWNER') & (merged['type_x'] == 'high-level')]
    return filtered.shape[0]

# Alternatively, using vectorized operations
def compute_feature_vectorized(card, disp):
    card_type = card['type_x'].map({'high-level': 1, 'low-level': 0})
    disp_type = disp['type'].map({'OWNER': 1, 'NON_OWNER': 0})
    return (card_type == disp_type).sum()

