import pandas as pd

def compute_region(client_id):
    client = client.merge(district, left_on='district_id', right_on='district_id', suffixes=('', '_district'))
    region = client['A2'].where(client['client_id'] == client_id, other=client['A2'].fillna(''))
    return region.fillna('Unknown')

print(compute_region(3541))

import pandas as pd

def count_jesenik_accounts():
    account = pd.merge(account, district, left_on='district_id', right_on='district_id')
    jesenik_accounts = account[account['A2'] == 'J']
    return len(jesenik_accounts['account_id'])

